### 1. Script SQL RPC para Purga Transaccional (`databasePurgeService`)

Esta función PL/pgSQL se ejecuta en el esquema `public`. Utiliza aislamiento transaccional estricto, valida el aislamiento por `tenant_id` extraído del contexto de seguridad de Supabase (`auth.jwt()`) y emplea bloqueos pesimistas (`FOR UPDATE`) para evitar condiciones de carrera durante el borrado masivo en cascada (Facturación $\to$ Inventario $\to$ Tesorería $\to$ Catálogos).

```sql
CREATE OR REPLACE FUNCTION public.rpc_purge_tenant_data(p_tenant_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_current_tenant UUID;
    v_deleted_invoices INT := 0;
    v_deleted_inventory INT := 0;
    v_deleted_customers INT := 0;
    v_deleted_products INT := 0;
BEGIN
    -- 1. Validar identidad del Tenant mediante JWT o parámetro estricto
    v_current_tenant := NULLIF(current_setting('request.jwt.claim.app_metadata', true)::jsonb->>'tenant_id', '')::UUID;

    IF v_current_tenant IS NULL THEN
        -- Fallback a validación explícita si se ejecuta desde rol superusuario autorizado
        v_current_tenant := p_tenant_id;
    END IF;

    IF v_current_tenant IS NULL OR v_current_tenant <> p_tenant_id THEN
        RAISE EXCEPTION 'Acceso denegado: Violación de aislamiento Multi-Tenant RLS.';
    END IF;

    -- 2. Bloqueo pesimista del tenant para serializar operaciones de purga
    PERFORM 1 FROM public.tenants WHERE id = v_current_tenant FOR UPDATE;

    -- 3. Ejecución de borrado en orden dependiente de FKs para evitar violaciones de integridad

    -- Facturación y Transacciones
    DELETE FROM public.invoice_items 
    WHERE invoice_id IN (SELECT id FROM public.invoices WHERE tenant_id = v_current_tenant);

    DELETE FROM public.invoices 
    WHERE tenant_id = v_current_tenant;
    GET DIAGNOSTICS v_deleted_invoices = ROW_COUNT;

    -- Tesorería y Pagos
    DELETE FROM public.payments 
    WHERE tenant_id = v_current_tenant;

    -- Inventario y Movimientos ABC
    DELETE FROM public.inventory_movements 
    WHERE tenant_id = v_current_tenant;

    DELETE FROM public.stock_levels 
    WHERE tenant_id = v_current_tenant;
    GET DIAGNOSTICS v_deleted_inventory = ROW_COUNT;

    -- Catálogos: Clientes
    DELETE FROM public.customers 
    WHERE tenant_id = v_current_tenant;
    GET DIAGNOSTICS v_deleted_customers = ROW_COUNT;

    -- Catálogos: Productos (25 productos semilla)
    DELETE FROM public.products 
    WHERE tenant_id = v_current_tenant;
    GET DIAGNOSTICS v_deleted_products = ROW_COUNT;

    -- 4. Retornar reporte de ejecución JSONB
    RETURN jsonb_build_object(
        'status', 'success',
        'tenant_id', v_current_tenant,
        'purged_at', clock_timestamp(),
        'metrics', jsonb_build_object(
            'invoices_deleted', v_deleted_invoices,
            'inventory_records_deleted', v_deleted_inventory,
            'customers_deleted', v_deleted_customers,
            'products_deleted', v_deleted_products
        )
    );

EXCEPTION WHEN OTHERS THEN
    -- Rollback automático garantizado por PL/pgSQL en excepciones
    RAISE EXCEPTION 'Error crítico en rpc_purge_tenant_data: %', SQLERRM;
END;
$$;

-- Otorgar permisos de ejecución al rol autenticado
GRANT EXECUTE ON FUNCTION public.rpc_purge_tenant_data(UUID) TO authenticated;
```

