### 2. Implementación de `databasePurgeService.ts` (TypeScript / Supabase Client)

Servicio encapsulado para invocar la función RPC con tipado estricto y manejo de errores transaccionales.

```typescript
import { supabase } from '../lib/supabase';

export interface PurgeResult {
  status: string;
  tenant_id: string;
  purged_at: string;
  metrics: {
    invoices_deleted: number;
    inventory_records_deleted: number;
    customers_deleted: number;
    products_deleted: number;
  };
}

export const databasePurgeService = {
  async purgeTenantData(tenantId: string): Promise<PurgeResult> {
    const { data, error } = await supabase.rpc('rpc_purge_tenant_data', {
      p_tenant_id: tenantId,
    });

    if (error) {
      throw new Error(`Fallo en la purga de datos del tenant: ${error.message}`);
    }

    return data as PurgeResult;
  },
};
```

