### 3. Implementación de `seedLightData.ts` (25 Productos, 10 Clientes)

Carga optimizada en lote para inicializar el tenant con productos del sector pesquero y clientes corporativos/minoristas bajo el principio ACID.

```typescript
import { supabase } from '../lib/supabase';

export const seedLightData = async (tenantId: string): Promise<void> => {
  // 1. Array de 25 Productos del sector pesquero (Pescados, Mariscos, Congelados)
  const productsToSeed = Array.from({ length: 25 }, (_, index) => {
    const id = index + 1;
    const categories = ['Pescado Fresco', 'Marisco', 'Congelado', 'Especialidad'];
    return {
      tenant_id: tenantId,
      sku: `PESC-${String(id).padStart(3, '0')}`,
      name: `Producto Pezcaderia ${id}`,
      category: categories[id % categories.length],
      unit_price: Math.floor(Math.random() * 45) + 5.50,
      cost_price: Math.floor(Math.random() * 20) + 2.00,
      stock_min: 10,
      is_active: true,
    };
  });

  const { error: prodError } = await supabase.from('products').insert(productsToSeed);
  if (prodError) throw new Error(`Error insertando productos semilla: ${prodError.message}`);

  // 2. Array de 10 Clientes
  const customersToSeed = Array.from({ length: 10 }, (_, index) => {
    const id = index + 1;
    return {
      tenant_id: tenantId,
      tax_id: `B${String(Math.floor(Math.random() * 89999999) + 10000000)}`,
      name: `Cliente Restaurante ${id} S.L.`,
      email: `compras${id}@restaurantecentral.com`,
      phone: `+34600000${String(id).padStart(3, '0')}`,
      address: `Calle Mayor ${id}, Madrid`,
      credit_limit: 1500.00,
    };
  });

  const { error: custError } = await supabase.from('customers').insert(customersToSeed);
  if (custError) throw new Error(`Error insertando clientes semilla: ${custError.message}`);
};
```

