### 5. Integración en `EnterpriseTopbar.tsx`

Incorporación del botón de purga y reseteo a datos semilla directamente en la barra de navegación superior de nivel empresarial con confirmación de seguridad.

```tsx
import React, { useState } from 'react';
import { Trash2, RefreshCw, AlertTriangle } from 'lucide-react';
import { databasePurgeService } from '../services/databasePurgeService';
import { seedLightData } from '../services/seedLightData';

interface EnterpriseTopbarProps {
  tenantId: string;
  onDataReset?: () => void;
}

export const EnterpriseTopbar: React.FC<EnterpriseTopbarProps> = ({ tenantId, onDataReset }) => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handlePurgeAndSeed = async () => {
    if (!window.confirm('ADVERTENCIA: Esta acción eliminará toda la data transaccional y cargará los datos semilla (25 productos, 10 clientes). ¿Desea continuar?')) {
      return;
    }

    setLoading(true);
    setError(null);

    try {
      // 1. Purga transaccional vía RPC
      await databasePurgeService.purgeTenantData(tenantId);

      // 2. Carga de datos semilla ligeros
      await seedLightData(tenantId);

      if (onDataReset) {
        onDataReset();
      }

      alert('Base de datos depurada y reinicializada con éxito.');
    } catch (err: any) {
      setError(err.message || 'Error desconocido durante el reseteo.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <header className="h-16 bg-slate-900 border-b border-slate-800 px-6 flex items-center justify-between text-white">
      <div className="flex items-center space-x-4">
        <h1 className="text-lg font-bold tracking-wide text-cyan-400">LA PEZCADERIA ERP</h1>
        <span className="text-xs bg-cyan-950 text-cyan-300 px-2.5 py-1 rounded-full border border-cyan-800">
          Enterprise Multi-Tenant
        </span>
      </div>

      <div className="flex items-center space-x-4">
        {error && <span className="text-xs text-red-400 font-medium">{error}</span>}
        <button
          onClick={handlePurgeAndSeed}
          disabled={loading}
          className="flex items-center space-x-2 bg-red-900/40 hover:bg-red-900/70 border border-red-700/50 px-3 py-1.5 rounded text-xs font-semibold text-red-200 transition-colors disabled:opacity-50"
          title="Purgar base de datos y cargar semilla ligera"
        >
          {loading ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Trash2 className="w-4 h-4" />}
          <span>{loading ? 'Procesando...' : 'Purga & Seed (25/10)'}</span>
        </button>
      </div>
    </header>
  );
};
```
